import { tryResolveAddMcpAgentId } from "../mcp/agents.js";
import "../init/agents.js";
import { detectSkillsAgents, skillsInstallableAgents } from "./targets.js";
import { collectYesAgents, noDetectedAgentsMessage } from "../init/plan.js";
import { detectAgent } from "../init/detect_host.js";
import { agentChoicesFrom, pickAgentsInteractively, resolveAgentSelection } from "../utils/agent_picker.js";
import { invocationsForSelection, resolveSkillId, uniqueSkillEntries, yesInstallInvocations } from "./catalog.js";
import { pickSkillsInteractively } from "./wizard.js";
//#region src/skills/plan.ts
const assertSkillsCanRun = (options) => {
	if (options.action === "update") {
		if (options.yes || options.interactive) return;
		throw new Error("No interactive terminal. Pass -y to update installed skills.");
	}
	if (options.yes || options.interactive || options.hasSkills === true) return;
	throw new Error("No interactive terminal. Pass -y to install the default skills into detected agents, or --skill <name>.");
};
async function resolveSkillsPlan(options) {
	assertSkillsCanRun({
		yes: options.yes,
		interactive: options.interactive,
		action: "install",
		hasSkills: options.skills.length > 0
	});
	const specified = uniqueSkillEntries(options.skills.map(resolveSkillId));
	const prompt = options.interactive && !options.yes;
	const scope = options.global ? "global" : "project";
	const available = skillsInstallableAgents();
	const availableSet = new Set(available);
	const scoped = await detectSkillsAgents({
		scope,
		cwd: options.cwd,
		...options.detectInstalledAgents ? { detectInstalledAgents: options.detectInstalledAgents } : {}
	});
	const detected = options.yes && options.agents.length === 0 ? await collectYesAgents({
		detected: () => scoped,
		detectAgent: options.detectAgent ?? detectAgent,
		acceptHost: (id) => availableSet.has(id)
	}) : scoped;
	const selected = await resolveAgentSelection({
		specified: options.agents,
		choices: agentChoicesFrom(available, detected),
		detected,
		message: "Which coding agents should get Neon agent skills? (space to toggle, enter to confirm)",
		nonInteractiveMessage: noDetectedAgentsMessage({
			scope,
			supported: available,
			fix: options.yes ? "run-without-yes" : "pass-yes",
			nameAgent: true
		}),
		resolveSpecified: (raw) => {
			if (raw === "*") throw new Error("neon skills does not accept --agent *. Pass --agent <name> for each coding agent, or omit --agent to use detected agents.");
			const id = tryResolveAddMcpAgentId(raw);
			if (!id) throw new Error(`Unknown agent: "${raw}". Supported agents: ${available.join(", ")}`);
			return id;
		},
		pick: prompt ? options.pickAgents ?? pickAgentsInteractively : void 0,
		interactive: prompt
	});
	const agents = selected.filter((id) => available.includes(id));
	const skipped = selected.filter((id) => !available.includes(id));
	if (agents.length === 0) throw new Error(`None of the selected agents can install skills. Supported agents: ${available.join(", ")}`);
	return {
		scope,
		agents,
		skipped,
		invocations: specified.length > 0 ? invocationsForSelection(specified) : options.yes ? yesInstallInvocations() : invocationsForSelection(await (options.pickSkills ?? pickSkillsInteractively)())
	};
}
//#endregion
export { assertSkillsCanRun, resolveSkillsPlan };
